steps.starter_content:
# Policy for the shop application
path "*" {
  capabilities = ["create", "read", "update", "delete", "list", "sudo"]
}

steps.hint:
Each rule is:
  path "secret/data/shop/*" {
    capabilities = ["read"]
  }
The key-value engine (version 2) keeps values under secret/data/... and names under secret/metadata/..., so the app needs both paths. Remove the path "*" block completely.

steps.solution:
# Policy for the shop application
path "secret/data/shop/*" {
  capabilities = ["read"]
}

path "secret/metadata/shop/*" {
  capabilities = ["list", "read"]
}

path "database/creds/shop-readonly" {
  capabilities = ["read"]
}
